package auth

import (
	"errors"
	"fmt"
	"net/url"
	"strings"
	"time"

	"github.com/entireio/auth-go/tokens"
	"github.com/entireio/cli/cmd/entire/cli/api"
	"github.com/entireio/cli/internal/entireclient/contexts"
	"github.com/entireio/cli/internal/entireclient/tokenstore"
)

// defaultContextTokenTTL is the encoded keychain expiry used when a login
// token carries no usable exp claim (e.g. an opaque, non-JWT bearer). The
// server is the real authority on validity; this only governs when local
// readers consider the token stale, and we hold no refresh token to act on
// it, so a conservative non-zero value is enough to keep the entry usable.
const defaultContextTokenTTL = time.Hour

// RecordLoginContext records a freshly obtained login token in the
// shared contexts.json credential model: it derives the issuer (core
// URL), handle, and expiry from the token's own claims, stores the token
// in the OS keyring under the entire-core:<issuer> service scheme entiredb
// uses, and writes (or updates) the matching context.
//
// Contexts are keyed by identity (core URL + handle): re-logging into the
// same identity updates its context in place, while a second identity on
// the same core gets its own context (named handle@host) instead of
// clobbering the first.
//
// activate controls current_context: login passes true (the just-completed
// login becomes active, kubectl use-context style); read-time migration
// passes false so it never silently switches the user's active account —
// it still sets current_context when none exists yet.
//
// This is the contexts.json half of login's dual-write: the legacy
// entire-cli/<authBaseURL> keyring entry is still written by the caller so
// the control-plane readers keep working untouched during the transition.
// A login recorded here is visible to entiredb's CLIs (and the in-CLI git
// remote helper) because they share this file and keychain layout.
//
// Returns the context name on success. Errors are returned (not swallowed)
// so the caller can warn; login still succeeds on the legacy entry.
func RecordLoginContext(rawToken, refreshToken string, activate bool) (string, error) {
	claims, err := tokens.ParseClaims(rawToken)
	if err != nil {
		return "", fmt.Errorf("parse login token claims: %w", err)
	}
	coreURL := claims.Issuer
	if coreURL == "" {
		return "", errors.New("login token has no iss claim; cannot derive core URL for a context")
	}
	handle := claims.Handle
	if handle == "" {
		handle = claims.Subject
	}
	if handle == "" {
		return "", errors.New("login token has no handle/sub claim; cannot key the keychain slot")
	}

	keychainService := tokenstore.CoreKeyringService(coreURL)

	expiresIn := int64(defaultContextTokenTTL.Seconds())
	if !claims.ExpiresAt.IsZero() {
		if secs := int64(time.Until(claims.ExpiresAt).Seconds()); secs > 0 {
			expiresIn = secs
		}
	}

	// The refresh token lives in the paired "<service>:refresh" slot (raw,
	// no expiry suffix). Clear any prior one when this login carries none,
	// so a stale token from an earlier session can't later be replayed
	// against the server's single-use rotation and revoke the family.
	//
	// Write the refresh slot BEFORE the access token, matching
	// contextTokenStore.SaveTokens: a partial write must never leave a fresh
	// access token paired with a stale refresh token left over from an
	// earlier login. Refresh-first means a failed refresh write aborts before
	// the access token is touched (old pair preserved), rather than committing
	// a new access JWT against a dead refresh token.
	refreshSlot := tokenstore.RefreshService(keychainService)
	if refreshToken != "" {
		if err := tokenstore.Set(refreshSlot, handle, refreshToken); err != nil {
			return "", fmt.Errorf("store refresh token in keyring: %w", err)
		}
	} else {
		_ = tokenstore.Delete(refreshSlot, handle) //nolint:errcheck // best-effort cleanup of a stale refresh token
	}

	encoded := tokenstore.EncodeTokenWithExpiration(rawToken, expiresIn)
	if err := tokenstore.Set(keychainService, handle, encoded); err != nil {
		return "", fmt.Errorf("store login token in keyring: %w", err)
	}

	var name string
	cfgDir := contexts.DefaultConfigDir()
	if modErr := contexts.Modify(cfgDir, func(f *contexts.File) (bool, error) {
		name = pickContextName(f, coreURL, handle)
		f.Upsert(&contexts.Context{
			Name:            name,
			CoreURL:         coreURL,
			Handle:          handle,
			KeychainService: keychainService,
		})
		if activate || f.CurrentContext == "" {
			f.CurrentContext = name
		}
		return true, nil
	}); modErr != nil {
		return "", fmt.Errorf("write context: %w", modErr)
	}

	return name, nil
}

// pickContextName chooses the contexts.json name for an (coreURL, handle)
// identity within f. An existing context for the same identity keeps its
// name (re-login updates in place). A fresh identity prefers the bare core
// host; if a *different* identity already holds that name, it's qualified
// with the handle (handle@host) so the two don't collide — and, in the
// pathological case that's taken too, a numeric suffix guarantees
// uniqueness.
func pickContextName(f *contexts.File, coreURL, handle string) string {
	for _, c := range f.Contexts {
		if sameIssuer(c.CoreURL, coreURL) && c.Handle == handle {
			return c.Name
		}
	}
	host := contextNameForCoreURL(coreURL)
	if f.Find(host) == nil {
		return host
	}
	qualified := handle + "@" + host
	if f.Find(qualified) == nil {
		return qualified
	}
	for i := 2; ; i++ {
		candidate := fmt.Sprintf("%s-%d", qualified, i)
		if f.Find(candidate) == nil {
			return candidate
		}
	}
}

// sameIssuer compares two core URLs ignoring a trailing slash.
func sameIssuer(a, b string) bool {
	return strings.TrimRight(a, "/") == strings.TrimRight(b, "/")
}

// MigrateLegacyLoginContext bridges users who logged in before the
// contexts.json dual-write existed: if the legacy entire-cli/<authBaseURL>
// keyring entry holds a usable JWT and no context yet covers its issuer,
// it records an equivalent context (and keychain entry under the shared
// scheme) so the git remote helper can authenticate without a re-login.
//
// Returns (true, nil) when it created a context. No-ops — returning
// (false, nil) — when there's no legacy token, the token is opaque
// (no derivable issuer), or a context for that issuer already exists.
// Idempotent: safe to call on every helper invocation.
func MigrateLegacyLoginContext() (migrated bool, err error) {
	legacy, err := NewStore().GetToken(api.AuthBaseURL())
	if err != nil {
		return false, fmt.Errorf("read legacy login token: %w", err)
	}
	if legacy == "" {
		return false, nil
	}
	claims, parseErr := tokens.ParseClaims(legacy)
	if parseErr != nil || claims.Issuer == "" {
		// Opaque/unsigned legacy token — can't derive a context from it.
		return false, nil //nolint:nilerr // absence of a JWT issuer is not an error here
	}
	handle := claims.Handle
	if handle == "" {
		handle = claims.Subject
	}
	f, err := contexts.Load(contexts.DefaultConfigDir())
	if err != nil {
		return false, fmt.Errorf("load contexts: %w", err)
	}
	// Skip only when this exact identity is already represented. Keying on
	// issuer alone would skip a legacy bob@core just because alice@core (e.g.
	// from another CLI) already exists, leaving Bob without a context.
	for _, c := range f.Contexts {
		if sameIssuer(c.CoreURL, claims.Issuer) && c.Handle == handle {
			return false, nil
		}
	}
	// activate=false: migrating an old login (e.g. on first `git clone`) must
	// not silently switch the user's active context. RecordLoginContext still
	// sets current_context when none exists yet.
	// No refresh token: the legacy entry is access-token-only.
	if _, err := RecordLoginContext(legacy, "", false); err != nil {
		return false, err
	}
	return true, nil
}

// LoginTokenForContext returns the login JWT stored for c, read from the
// OS keyring slot the context points at. The encoded expiry is stripped;
// the server is the authority on validity and the device-flow login holds
// no refresh token, so an expired token surfaces as a 401 the caller can
// translate into a re-login hint.
func LoginTokenForContext(c *contexts.Context) (string, error) {
	if c == nil {
		return "", errors.New("nil context")
	}
	if c.KeychainService == "" || c.Handle == "" {
		return "", fmt.Errorf("context %q has no keychain slot", c.Name)
	}
	encoded, err := tokenstore.Get(c.KeychainService, c.Handle)
	if err != nil {
		return "", fmt.Errorf("read token for context %q: %w", c.Name, err)
	}
	if encoded == "" {
		return "", fmt.Errorf("no token stored for context %q (run `entire login`)", c.Name)
	}
	token, _ := tokenstore.DecodeTokenWithExpiration(encoded)
	return token, nil
}

// contextNameForCoreURL derives a stable, human-readable context name
// from the issuer URL — its host, matching entiredb's default of naming a
// context after the core it authenticates against. Falls back to the raw
// URL when it can't be parsed.
func contextNameForCoreURL(coreURL string) string {
	if u, err := url.Parse(coreURL); err == nil && u.Host != "" {
		return u.Host
	}
	return coreURL
}

package auth

import (
	"errors"
	"fmt"
	"strings"

	"github.com/entireio/auth-go/tokens"
	"github.com/entireio/auth-go/tokenstore"
	"github.com/entireio/cli/cmd/entire/cli/api"
	"github.com/zalando/go-keyring"
)

// keyringService is the OS-keyring service name for this CLI. Renaming
// would orphan every existing user's stored credentials — they'd appear
// logged out until they ran `entire login` again. Don't change this
// without a migration path.
const keyringService = "entire-cli"

// Store manages CLI authentication tokens via a pluggable backend. The
// production binary always resolves to the OS keyring. A file-backed
// backend is available only in builds tagged `authfilestore` (used by
// integration tests to avoid the OS keychain).
//
// Implements tokenstore.Store so it can be passed to tokenmanager.New
// as the persistence layer. The interface methods (SaveTokens /
// LoadTokens / DeleteTokens) delegate to the same backend as the
// legacy SaveToken / GetToken / DeleteToken pair, so production and
// test paths share a single source of truth.
type Store struct {
	service string
	backend tokenBackend
}

// tokenBackend abstracts token persistence. Implementations must treat
// "missing key" as a non-error: get returns ("", nil) and delete is a
// no-op so callers don't have to plumb backend-specific sentinels.
type tokenBackend interface {
	save(service, key, value string) error
	get(service, key string) (string, error)
	delete(service, key string) error
}

// chooseBackend returns the backend used by NewStore and
// NewStoreWithService. The default returns the keyring backend; the
// `authfilestore` build adds an init() that may swap in a file-backed
// backend when the test env var is set.
var chooseBackend = func() tokenBackend { return keyringBackend{} }

// NewStore returns a Store backed by the system keyring (or, in
// `authfilestore` builds, optionally a file-backed test store).
func NewStore() *Store {
	return &Store{service: keyringService, backend: chooseBackend()}
}

// NewStoreWithService returns a Store with a custom keyring service name (for testing).
// Honors the same backend selection as NewStore so tests that opt into the
// file-backed test store via env var see consistent behavior across both
// constructors.
func NewStoreWithService(service string) *Store {
	return &Store{service: service, backend: chooseBackend()}
}

// SaveToken persists an access token for the given base URL. Prefer
// SaveTokens (the tokenstore.Store interface method) for new callers;
// SaveToken is kept for the legacy direct-bearer call sites (login,
// logout, auth status/list/revoke) that don't go through the tokenmanager.
func (s *Store) SaveToken(baseURL, token string) error {
	token = strings.TrimSpace(token)
	if token == "" {
		return errors.New("refusing to save empty token")
	}
	return s.backend.save(s.service, baseURL, token)
}

// GetToken retrieves a stored token for the given base URL. Returns
// an empty string (and no error) if no token is stored, or if the
// stored value is JSON-shaped (defensive: pre-shim entries are
// opaque token strings, never JSON; a JSON blob in the keyring is
// corruption and must not be put on the wire as a bearer).
//
// Prefer LoadTokens (the tokenstore.Store interface method) for new
// callers — it returns the full TokenSet so refresh tokens and expiry
// survive the round trip. GetToken is retained for the direct-bearer
// call sites that only need the access token string.
func (s *Store) GetToken(baseURL string) (string, error) {
	raw, err := s.backend.get(s.service, baseURL)
	if err != nil {
		return "", err
	}
	if looksJSONShaped(raw) {
		return "", nil
	}
	return raw, nil
}

// looksJSONShaped reports whether the keyring value's first
// non-whitespace byte is '{' or '['. Used to reject corrupt /
// previous-encoding entries before they end up in an
// Authorization: Bearer header.
func looksJSONShaped(s string) bool {
	trimmed := strings.TrimLeft(s, " \t\r\n")
	if trimmed == "" {
		return false
	}
	return trimmed[0] == '{' || trimmed[0] == '['
}

// DeleteToken removes a stored token for the given base URL. Returns
// no error if the token does not exist. Prefer DeleteTokens (the
// tokenstore.Store interface method); DeleteToken is retained for
// direct-bearer call sites.
func (s *Store) DeleteToken(baseURL string) error {
	return s.backend.delete(s.service, baseURL)
}

// SaveTokens implements tokenstore.Store. Refresh token, scope, expiry,
// and token type are intentionally dropped — the entire device-flow
// surface doesn't issue refresh tokens, and the legacy keyring/file
// layout stores bare access-token strings. If refresh-token support
// lands, this method (and the tokenBackend interface) become the
// migration point.
func (s *Store) SaveTokens(profile string, t tokens.TokenSet) error {
	access := strings.TrimSpace(t.AccessToken)
	if access == "" {
		return errors.New("refusing to save empty access token")
	}
	return s.backend.save(s.service, profile, access)
}

// LoadTokens implements tokenstore.Store. Reads the bare-string entry
// and wraps it back into a TokenSet. Returns tokenstore.ErrNotFound
// when nothing is stored under the profile (or the stored value is
// JSON-shaped — see GetToken's note about defensive rejection of
// non-token blobs) so callers can errors.Is against the lib sentinel.
func (s *Store) LoadTokens(profile string) (tokens.TokenSet, error) {
	access, err := s.backend.get(s.service, profile)
	if err != nil {
		return tokens.TokenSet{}, err
	}
	if access == "" || looksJSONShaped(access) {
		return tokens.TokenSet{}, tokenstore.ErrNotFound
	}
	return tokens.TokenSet{AccessToken: access}, nil
}

// DeleteTokens implements tokenstore.Store.
func (s *Store) DeleteTokens(profile string) error {
	return s.backend.delete(s.service, profile)
}

// LookupCurrentToken retrieves the active login token. It prefers the
// current contexts.json context (so a login from this or entiredb's CLIs
// authenticates control-plane commands), falling back to the legacy entry
// keyed by the auth issuer (api.AuthBaseURL()) for pre-contexts logins.
func LookupCurrentToken() (string, error) {
	return NewContextStore().GetToken(api.AuthBaseURL())
}

// keyringBackend persists tokens in the OS keyring. Every operation is
// wrapped in callKeyringWithContext because the underlying keyring call
// can block indefinitely when no provider is reachable — most commonly
// a headless Linux host with no Secret Service running (gnome-keyring,
// kwalletd, KeePassXC), but the same hang shape exists on macOS when
// the Keychain prompt is suppressed or on Windows when Credential
// Manager misbehaves.
type keyringBackend struct{}

func (keyringBackend) save(service, key, value string) error {
	ctx, cancel := newKeyringContext()
	defer cancel()
	_, err := callKeyringWithContext(ctx, "save", func() (string, error) {
		return "", keyring.Set(service, key, value)
	})
	if err != nil {
		return fmt.Errorf("save token to keyring: %w", err)
	}
	return nil
}

func (keyringBackend) get(service, key string) (string, error) {
	ctx, cancel := newKeyringContext()
	defer cancel()
	token, err := callKeyringWithContext(ctx, "get", func() (string, error) {
		v, err := keyring.Get(service, key)
		if errors.Is(err, keyring.ErrNotFound) {
			return "", nil
		}
		if err != nil {
			return "", fmt.Errorf("keyring.Get: %w", err)
		}
		return v, nil
	})
	if err != nil {
		return "", fmt.Errorf("get token from keyring: %w", err)
	}
	return token, nil
}

func (keyringBackend) delete(service, key string) error {
	ctx, cancel := newKeyringContext()
	defer cancel()
	_, err := callKeyringWithContext(ctx, "delete", func() (string, error) {
		if err := keyring.Delete(service, key); err != nil && !errors.Is(err, keyring.ErrNotFound) {
			return "", fmt.Errorf("keyring.Delete: %w", err)
		}
		return "", nil
	})
	if err != nil {
		return fmt.Errorf("delete token from keyring: %w", err)
	}
	return nil
}

