1	package cli
2	
3	import (
4		"bytes"
5		"context"
6		"errors"
7		"net/http"
8		"strings"
9		"testing"
10		"time"
11	
12		"github.com/entireio/auth-go/sts"
13		"github.com/entireio/auth-go/tokenmanager"
14		"github.com/entireio/auth-go/tokens"
15		"github.com/entireio/auth-go/tokenstore"
16		"github.com/entireio/cli/cmd/entire/cli/api"
17		"github.com/entireio/cli/cmd/entire/cli/auth"
18	)
19	
20	const (
21		testBaseURL = "https://entire.io"
22		testAuthTok = "tok"
23		testTokenID = "target-id"
24	)
25	
26	// --- status -----------------------------------------------------------------
27	
28	func TestRunAuthStatus_NotLoggedIn(t *testing.T) {
29		t.Parallel()
30	
31		store := newMockTokenStore()
32	
33		listCalled := false
34		list := func(context.Context) ([]api.Token, error) {
35			listCalled = true
36			return nil, nil
37		}
38	
39		var out bytes.Buffer
40		if err := runAuthStatus(context.Background(), &out, store, list, testBaseURL); err != nil {
41			t.Fatalf("unexpected error: %v", err)
42		}
43	
44		if listCalled {
45			t.Fatal("ListTokens should not be called when no token is stored")
46		}
47		if !strings.Contains(out.String(), "Not logged in to "+testBaseURL) {
48			t.Fatalf("output = %q, want 'Not logged in' message", out.String())
49		}
50	}
51	
52	func TestRunAuthStatus_LoggedIn(t *testing.T) {
53		t.Parallel()
54	
55		store := newMockTokenStore()
56		store.tokens[testBaseURL] = testAuthTok
57	
58		list := func(context.Context) ([]api.Token, error) {
59			return []api.Token{
60				{ID: "a", Name: "laptop"},
61				{ID: "b", Name: "ci"},
62			}, nil
63		}
64	
65		var out bytes.Buffer
66		if err := runAuthStatus(context.Background(), &out, store, list, testBaseURL); err != nil {
67			t.Fatalf("unexpected error: %v", err)
68		}
69	
70		if !strings.Contains(out.String(), "Logged in to "+testBaseURL) {
71			t.Fatalf("output = %q, want 'Logged in' message", out.String())
72		}
73		if !strings.Contains(out.String(), "Active tokens on this account: 2") {
74			t.Fatalf("output = %q, want token count", out.String())
75		}
76	}
77	
78	func TestRunAuthStatus_TokenInvalid(t *testing.T) {
79		t.Parallel()
80	
81		store := newMockTokenStore()
82		store.tokens[testBaseURL] = testAuthTok
83	
84		list := func(context.Context) ([]api.Token, error) {
85			return nil, &api.HTTPError{StatusCode: http.StatusUnauthorized, Message: "Not authenticated"}
86		}
87	
88		var out bytes.Buffer
89		if err := runAuthStatus(context.Background(), &out, store, list, testBaseURL); err != nil {
90			t.Fatalf("unexpected error: %v", err)
91		}
92	
93		if !strings.Contains(out.String(), "no longer valid") {
94			t.Fatalf("output = %q, want invalid-token message", out.String())
95		}
96		if !strings.Contains(out.String(), "entire login") {
97			t.Fatalf("output = %q, want re-auth hint", out.String())
98		}
99	}
100	
101	// TestRunAuthStatus_STSRejectionRendersInvalidMessage pins fix #2: in
102	// split-host setups, STS rejection happens before any HTTP call to the
103	// data API, so the friendly "Token in keychain ... is no longer valid"
104	// message has to fire on the auth-go sts package's wrapped string
105	// (no typed sentinel) as well as the data-API 401 case above.
106	func TestRunAuthStatus_STSRejectionRendersInvalidMessage(t *testing.T) {
107		t.Parallel()
108	
109		store := newMockTokenStore()
110		store.tokens[testBaseURL] = testAuthTok
111	
112		list := func(context.Context) ([]api.Token, error) {
113			// Exact format auth-go's sts package emits for an invalid_grant
114			// 4xx (see internal/oauthhttp's readAPIError). Without the
115			// detection in isKeychainTokenRejected this would fall through
116			// to the generic "validate token: ..." error path and the user
117			// would see a raw STS string instead of the re-login hint.
118			return nil, errors.New("token exchange: status 400: invalid_grant: subject_token expired")
119		}
120	
121		var out bytes.Buffer
122		if err := runAuthStatus(context.Background(), &out, store, list, testBaseURL); err != nil {
123			t.Fatalf("unexpected error: %v", err)
124		}
125	
126		if !strings.Contains(out.String(), "no longer valid") {
127			t.Fatalf("output = %q, want invalid-token message", out.String())
128		}
129		if !strings.Contains(out.String(), "entire login") {
130			t.Fatalf("output = %q, want re-auth hint", out.String())
131		}
132	}
133	
134	// TestRunAuthStatus_ExpiredCoreTokenRendersInvalidMessage pins the
135	// other half of fix #2: the tokenmanager's preflight check returns
136	// auth.ErrNotLoggedIn when a stored core JWT's exp claim is in the
137	// past. The keyring read at the top of runAuthStatus still finds a
138	// non-empty entry, so the "Not logged in" branch doesn't fire — the
139	// helper has to route the wrapped sentinel to the same re-login hint.
140	func TestRunAuthStatus_ExpiredCoreTokenRendersInvalidMessage(t *testing.T) {
141		t.Parallel()
142	
143		store := newMockTokenStore()
144		store.tokens[testBaseURL] = testAuthTok
145	
146		list := func(context.Context) ([]api.Token, error) {
147			return nil, errors.New("resolve API token: " + auth.ErrNotLoggedIn.Error())
148		}
149		// errors.New above is intentionally string-only to defeat the
150		// detection — confirm the substring fallback alone isn't what's
151		// catching this case. The real production path wraps with %w.
152		listWithChain := func(context.Context) ([]api.Token, error) {
153			return nil, &wrappedTestError{msg: "resolve API token", inner: auth.ErrNotLoggedIn}
154		}
155	
156		// Sanity: string-only does NOT match (no sentinel chain).
157		var out1 bytes.Buffer
158		if err := runAuthStatus(context.Background(), &out1, store, list, testBaseURL); err == nil {
159			t.Fatal("string-only ErrNotLoggedIn should not match — keep the test honest")
160		}
161	
162		// Real path: errors.Is sees the sentinel through the %w chain.
163		var out2 bytes.Buffer
164		if err := runAuthStatus(context.Background(), &out2, store, listWithChain, testBaseURL); err != nil {
165			t.Fatalf("unexpected error: %v", err)
166		}
167		if !strings.Contains(out2.String(), "no longer valid") {
168			t.Fatalf("output = %q, want invalid-token message", out2.String())
169		}
170	}
171	
172	// wrappedTestError is a tiny stand-in for fmt.Errorf("...: %w", inner) — kept
173	// local so the test reads as "this is what production hands runAuthStatus".
174	type wrappedTestError struct {
175		msg   string
176		inner error
177	}
178	
179	func (e *wrappedTestError) Error() string { return e.msg + ": " + e.inner.Error() }
180	func (e *wrappedTestError) Unwrap() error { return e.inner }
181	
182	func TestRunAuthStatus_ServerError(t *testing.T) {
183		t.Parallel()
184	
185		store := newMockTokenStore()
186		store.tokens[testBaseURL] = testAuthTok
187	
188		list := func(context.Context) ([]api.Token, error) {
189			return nil, errors.New("connection refused")
190		}
191	
192		var out bytes.Buffer
193		err := runAuthStatus(context.Background(), &out, store, list, testBaseURL)
194		if err == nil {
195			t.Fatal("expected error for non-401 failure")
196		}
197		if !strings.Contains(err.Error(), "connection refused") {
198			t.Fatalf("error = %v, want underlying message", err)
199		}
200	}
201	
202	// --- list -------------------------------------------------------------------
203	
204	func TestRunAuthList_NotLoggedInErrors(t *testing.T) {
205		t.Parallel()
206	
207		store := newMockTokenStore()
208	
209		var out bytes.Buffer
210		err := runAuthList(context.Background(), &out, store,
211			func(context.Context) ([]api.Token, error) { return nil, nil },
212			testBaseURL, false)
213		if err == nil {
214			t.Fatal("expected error when not logged in")
215		}
216		if !strings.Contains(err.Error(), "not logged in") {
217			t.Fatalf("error = %v, want 'not logged in' message", err)
218		}
219	}
220	
221	func TestRunAuthList_TablePrintsRows(t *testing.T) {
222		t.Parallel()
223	
224		store := newMockTokenStore()
225		store.tokens[testBaseURL] = testAuthTok
226	
227		lastUsed := "2026-04-01T12:00:00Z"
228		list := func(context.Context) ([]api.Token, error) {
229			return []api.Token{
230				{ID: "tok-1", Name: "laptop", Scope: "cli",
231					CreatedAt:  "2026-01-01T00:00:00Z",
232					ExpiresAt:  "2027-01-01T00:00:00Z",
233					LastUsedAt: &lastUsed},
234				{ID: "tok-2", Name: "ci", Scope: "cli",
235					CreatedAt:  "2026-02-01T00:00:00Z",
236					ExpiresAt:  "2027-01-01T00:00:00Z",
237					LastUsedAt: nil},
238			}, nil
239		}
240	
241		var out bytes.Buffer
242		if err := runAuthList(context.Background(), &out, store, list, testBaseURL, false); err != nil {
243			t.Fatalf("unexpected error: %v", err)
244		}
245	
246		output := out.String()
247		if !strings.Contains(output, "ID") || !strings.Contains(output, "NAME") {
248			t.Fatalf("output = %q, want table headers", output)
249		}
250		if !strings.Contains(output, "tok-1") || !strings.Contains(output, "laptop") {
251			t.Fatalf("output = %q, want first row", output)
252		}
