// makeContextJWT builds a JWT-shaped token (non-"none" alg) carrying the
// given claims, which is all RecordLoginContext needs.
func makeContextJWT(t *testing.T, payloadJSON string) string {
	t.Helper()
	enc := base64.RawURLEncoding
	header := enc.EncodeToString([]byte(`{"alg":"HS256","typ":"JWT"}`))
	return header + "." + enc.EncodeToString([]byte(payloadJSON)) + "." + enc.EncodeToString([]byte("sig"))
}

func TestRunAuthContexts(t *testing.T) {
	cfgDir := t.TempDir()
	t.Setenv("ENTIRE_CONFIG_DIR", cfgDir)
	restore := tokenstore.UseFileBackendForTesting(filepath.Join(t.TempDir(), "tokens.json"))
	t.Cleanup(restore)

	var empty bytes.Buffer
	if err := runAuthContexts(&empty); err != nil {
		t.Fatalf("runAuthContexts (empty): %v", err)
	}
	if !strings.Contains(empty.String(), "No login contexts") {
		t.Fatalf("empty listing = %q, want a 'No login contexts' hint", empty.String())
	}

	exp := time.Now().Add(time.Hour).Unix()
	token := makeContextJWT(t, fmt.Sprintf(`{"iss":"https://core.example.com","handle":"alice","exp":%d}`, exp))
	if _, err := auth.RecordLoginContext(token, "", true); err != nil {
		t.Fatalf("RecordLoginContext: %v", err)
	}

	var out bytes.Buffer
	if err := runAuthContexts(&out); err != nil {
		t.Fatalf("runAuthContexts: %v", err)
	}
	got := out.String()
	if !strings.Contains(got, "* core.example.com") {
		t.Fatalf("listing = %q, want current-marked core.example.com", got)
	}
	if !strings.Contains(got, "alice") {
		t.Fatalf("listing = %q, want handle alice", got)
	}
}

func TestWarnIfCrossCoreContext(t *testing.T) {
	cfgDir := t.TempDir()
	t.Setenv("ENTIRE_CONFIG_DIR", cfgDir)
	t.Setenv("ENTIRE_AUTH_BASE_URL", "https://auth.example.com")
	restore := tokenstore.UseFileBackendForTesting(filepath.Join(t.TempDir(), "tokens.json"))
	t.Cleanup(restore)

	exp := time.Now().Add(time.Hour).Unix()

	// Same core as the configured auth host: no warning.
	sameName, err := auth.RecordLoginContext(makeContextJWT(t, fmt.Sprintf(`{"iss":"https://auth.example.com","handle":"alice","exp":%d}`, exp)), "", true)
	if err != nil {
		t.Fatalf("record same-core: %v", err)
	}
	var same bytes.Buffer
	warnIfCrossCoreContext(&same, sameName)
	if same.Len() != 0 {
		t.Fatalf("same-core context should not warn, got: %q", same.String())
	}

	// Different core: warns that the control plane won't follow.
	otherName, err := auth.RecordLoginContext(makeContextJWT(t, fmt.Sprintf(`{"iss":"https://other.example.com","handle":"alice","exp":%d}`, exp)), "", true)
	if err != nil {
		t.Fatalf("record cross-core: %v", err)
	}
	var diff bytes.Buffer
	warnIfCrossCoreContext(&diff, otherName)
	if !strings.Contains(diff.String(), "other.example.com") || !strings.Contains(diff.String(), "control-plane") {
		t.Fatalf("cross-core context should warn, got: %q", diff.String())
	}
}

func TestNoteRemainingLogins(t *testing.T) {
	cfgDir := t.TempDir()
	t.Setenv("ENTIRE_CONFIG_DIR", cfgDir)
	restore := tokenstore.UseFileBackendForTesting(filepath.Join(t.TempDir(), "tokens.json"))
	t.Cleanup(restore)

	// No contexts: silent.
	var empty bytes.Buffer
	noteRemainingLogins(&empty)
	if empty.Len() != 0 {
		t.Fatalf("no remaining contexts should be silent, got %q", empty.String())
	}

	// A surviving context: names it and points at --all.
	exp := time.Now().Add(time.Hour).Unix()
	if _, err := auth.RecordLoginContext(makeContextJWT(t, fmt.Sprintf(`{"iss":"https://core.example.com","handle":"alice","exp":%d}`, exp)), "", true); err != nil {
		t.Fatalf("record: %v", err)
	}
	var buf bytes.Buffer
	noteRemainingLogins(&buf)
	if !strings.Contains(buf.String(), "core.example.com") || !strings.Contains(buf.String(), "--all") {
		t.Fatalf("expected note naming the context and --all, got %q", buf.String())
	}
}

package cli

import (
	"bytes"
	"context"
	"errors"
	"net/http"
	"strings"
	"testing"

	"github.com/entireio/cli/cmd/entire/cli/api"
)

const testLogoutToken = "tok123"

type mockTokenStore struct {
	tokens     map[string]string
	deleted    map[string]bool
	getErr     error
	deleteErr  error
	getCalls   int
	deleteCall int
}

func newMockTokenStore() *mockTokenStore {
	return &mockTokenStore{
		tokens:  make(map[string]string),
		deleted: make(map[string]bool),
	}
}

func (m *mockTokenStore) GetToken(baseURL string) (string, error) {
	m.getCalls++
	if m.getErr != nil {
		return "", m.getErr
	}
	return m.tokens[baseURL], nil
}

func (m *mockTokenStore) DeleteToken(baseURL string) error {
	m.deleteCall++
	if m.deleteErr != nil {
		return m.deleteErr
	}
	m.deleted[baseURL] = true
	return nil
}

func TestRunLogout_RevokesServerSideThenDeletesLocally(t *testing.T) {
	t.Parallel()

	store := newMockTokenStore()
	store.tokens["https://entire.io"] = testLogoutToken

	revokeCalled := false
	revoke := func(context.Context) error {
		revokeCalled = true
		return nil
	}

	var out, errOut bytes.Buffer
	err := runLogout(context.Background(), &out, &errOut, store, revoke, func(context.Context) error { return nil }, func() error { return nil }, "https://entire.io", false)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	if !revokeCalled {
		t.Error("revoke should be called when a local token exists")
	}
	if !store.deleted["https://entire.io"] {
		t.Fatal("expected token to be deleted for https://entire.io")
	}
	if !strings.Contains(out.String(), "Logged out.") {
		t.Fatalf("stdout = %q, want to contain %q", out.String(), "Logged out.")
	}
	if errOut.Len() != 0 {
		t.Fatalf("stderr = %q, want empty", errOut.String())
	}
}

func TestRunLogout_NoTokenSkipsRevoke(t *testing.T) {
	t.Parallel()

	store := newMockTokenStore() // no token stored

	revokeCalled := false
	revoke := func(context.Context) error {
		revokeCalled = true
		return nil
	}

	var out, errOut bytes.Buffer
	err := runLogout(context.Background(), &out, &errOut, store, revoke, func(context.Context) error { return nil }, func() error { return nil }, "https://entire.io", false)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	if revokeCalled {
		t.Fatal("revoke should not be called when no local token exists")
	}
	if !store.deleted["https://entire.io"] {
		t.Fatal("expected DeleteToken to be called even when no token was stored")
	}
	if !strings.Contains(out.String(), "Logged out.") {
		t.Fatalf("stdout = %q, want to contain %q", out.String(), "Logged out.")
	}
}

func TestRunLogout_RevokeFailureWarnsButSucceeds(t *testing.T) {
	t.Parallel()

	store := newMockTokenStore()
	store.tokens["https://entire.io"] = testLogoutToken

	revoke := func(context.Context) error {
		return errors.New("connection refused")
	}

	var out, errOut bytes.Buffer
	err := runLogout(context.Background(), &out, &errOut, store, revoke, func(context.Context) error { return nil }, func() error { return nil }, "https://entire.io", false)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	if !store.deleted["https://entire.io"] {
		t.Fatal("local token should still be deleted when server revoke fails")
	}
	if !strings.Contains(errOut.String(), "server-side token revocation failed") {
		t.Fatalf("stderr = %q, want warning about revoke failure", errOut.String())
	}
	if !strings.Contains(errOut.String(), "connection refused") {
		t.Fatalf("stderr = %q, want underlying error message", errOut.String())
	}
	if !strings.Contains(out.String(), "Logged out.") {
		t.Fatalf("stdout = %q, want to contain %q", out.String(), "Logged out.")
	}
}

func TestRunLogout_RevokeUnauthorizedIsSilent(t *testing.T) {
	t.Parallel()

	store := newMockTokenStore()
	store.tokens["https://entire.io"] = testLogoutToken

	revoke := func(context.Context) error {
		return &api.HTTPError{StatusCode: http.StatusUnauthorized, Message: "Not authenticated"}
	}

	var out, errOut bytes.Buffer
	err := runLogout(context.Background(), &out, &errOut, store, revoke, func(context.Context) error { return nil }, func() error { return nil }, "https://entire.io", false)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	if !store.deleted["https://entire.io"] {
		t.Fatal("local token should still be deleted after silent 401")
	}
	if errOut.Len() != 0 {
		t.Fatalf("stderr = %q, want empty for already-invalid token", errOut.String())
	}
	if !strings.Contains(out.String(), "Logged out.") {
		t.Fatalf("stdout = %q, want to contain %q", out.String(), "Logged out.")
	}
}

func TestRunLogout_GetTokenErrorWarnsAndFallsThrough(t *testing.T) {
	t.Parallel()

	store := newMockTokenStore()
	store.getErr = errors.New("keyring locked for read")

	revokeCalled := false
	revoke := func(context.Context) error {
		revokeCalled = true
		return nil
	}

	var out, errOut bytes.Buffer
	err := runLogout(context.Background(), &out, &errOut, store, revoke, func(context.Context) error { return nil }, func() error { return nil }, "https://entire.io", false)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	if revokeCalled {
		t.Fatal("revoke should not be called when token read fails")
	}
	if !store.deleted["https://entire.io"] {
		t.Fatal("DeleteToken should still be attempted after GetToken failure")
	}
	if !strings.Contains(errOut.String(), "failed to read token before revocation") {
		t.Fatalf("stderr = %q, want warning about read failure", errOut.String())
	}
}

func TestRunLogout_ReturnsErrorOnDeleteFailure(t *testing.T) {
	t.Parallel()

	store := newMockTokenStore()
	store.tokens["https://entire.io"] = testLogoutToken
	store.deleteErr = errors.New("keyring locked")

	revoke := func(context.Context) error { return nil }

	var out, errOut bytes.Buffer
	err := runLogout(context.Background(), &out, &errOut, store, revoke, func(context.Context) error { return nil }, func() error { return nil }, "https://entire.io", false)
	if err == nil {
		t.Fatal("expected error, got nil")
	}
	if !strings.Contains(err.Error(), "keyring locked") {
		t.Fatalf("error = %q, want to contain %q", err.Error(), "keyring locked")
	}
	if strings.Contains(out.String(), "Logged out.") {
		t.Fatal("should not print success message when local delete fails")
	}
}

func TestRunLogout_AllRevokesAllSessions(t *testing.T) {
	t.Parallel()

	store := newMockTokenStore()
	store.tokens["https://entire.io"] = testLogoutToken

	currentCalled, allCalled := false, false
	revokeCurrent := func(context.Context) error { currentCalled = true; return nil }
	revokeAll := func(context.Context) error { allCalled = true; return nil }

	var out, errOut bytes.Buffer
	err := runLogout(context.Background(), &out, &errOut, store,
		revokeCurrent, revokeAll, func() error { return nil }, "https://entire.io", true)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	if currentCalled {
		t.Error("--all should not call the current-session revoke")
	}
	if !allCalled {
		t.Error("--all should call the revoke-all path")
	}
	if !store.deleted["https://entire.io"] {
		t.Fatal("local token should still be deleted under --all")
	}
	if !strings.Contains(out.String(), "Logged out.") {
		t.Fatalf("stdout = %q, want to contain %q", out.String(), "Logged out.")
	}
}

func TestLogoutCmd_IsRegistered(t *testing.T) {
	t.Parallel()

	root := NewRootCmd()
	found := false
	for _, c := range root.Commands() {
		if c.Use == "logout" {
			found = true
			break
		}
	}
	if !found {
		t.Fatal("logout command not registered on root")
	}
}

