apiTokenRoutes.delete(
  "/current",
  requireBearerAuth,
  describeRoute({
    tags: ["ApiTokens"],
    summary: "Revoke the API token used to authenticate this request",
    description:
      "Revokes the ent_ bearer token that authenticated this request. Only valid for ent_ tokens — " +
      "callers authenticated with an entire-core JWT must revoke via entire-core's surface.",
    responses: {
      200: {
        description: "Token revoked",
        content: { "application/json": { schema: resolver(successResponseSchema) } },
      },
      400: {
        description: "Caller authenticated with a JWT — revoke via entire-core",
        content: { "application/json": { schema: resolver(errorSchema) } },
      },
      401: {
        description: "Not authenticated",
        content: { "application/json": { schema: resolver(errorSchema) } },
      },
    },
  }),
  async (c) => {
    const userId = c.get("userId")
    const tokenId = c.get("apiTokenId")
    if (!tokenId) {
      return c.json({ error: "Revoke entire-core JWTs via entire-core, not this endpoint" }, 400)
