20	// sessionLister lists the authenticated user's active login sessions — the
21	// server-side refresh-token families, one per `entire login` across all
22	// devices — surfaced by `entire auth status`. The implementation resolves its
23	// own data-API bearer via auth.TokenForResource (RFC 8693 exchange in
24	// split-host setups, same-host shortcut otherwise); callers don't pass a
25	// bearer through, which removes the temptation to forward the wrong-audience
26	// keyring token.
27	type sessionLister func(ctx context.Context) ([]api.Session, error)
28	
29	// User-visible placeholder strings. Promoted to constants so tests and
30	// production share a single source of truth.
31	const (
32		placeholderDash = "-"
33		lastUsedNever   = "never"
34		lastUsedJustNow = "just now"
35	)
36	
37	// requireSecureBaseURL enforces TLS unless insecureHTTPAuth is set. Every
38	// command that sends a bearer token over the network (login, logout,
39	// auth status) must call this so credentials don't leak over plaintext HTTP
40	// without explicit opt-in.
41	//
42	// Both the auth and data API origins are checked: the bearer travels to the
43	// auth host for login + session management, and to the data host for
44	// search/activity/dispatch/etc. When both origins resolve to the same host
45	// (e.g. an explicitly collapsed single-host deployment) the redundant second
46	// parse is skipped.
47	//
48	// When the opt-in flag is set, the tokenmanager's matching HTTP guard is
49	// also relaxed via auth.EnableInsecureHTTP — otherwise an STS exchange
50	// against a private-network http:// auth host would fail at the
51	// tokenmanager layer even though the per-command TLS check was waived.
52	func requireSecureBaseURL(insecureHTTPAuth bool) error {
53		if insecureHTTPAuth {
54			auth.EnableInsecureHTTP()
55			return nil
56		}
57		dataURL, authURL := api.BaseURL(), api.AuthBaseURL()
58		if err := api.RequireSecureURL(dataURL); err != nil {
59			return fmt.Errorf("base URL check: %w", err)
60		}
61		if authURL == dataURL {
62			return nil
63		}
64		if err := api.RequireSecureURL(authURL); err != nil {
65			return fmt.Errorf("auth base URL check: %w", err)
66		}
67		return nil
68	}
69	
70	// newSessionsClient builds an api.Client for the session management endpoints
71	// (list / revoke / current). These live on the data API regardless of
72	// split-host config — the auth host (entire-core in v2) mints OAuth tokens but
73	// doesn't host the session management endpoints — so this targets
74	// api.BaseURL().
75	//
76	// The supplied token must already be scoped for api.BaseURL(). Callers
77	// must obtain it via resolveDataAPIToken (or auth.TokenForResource
78	// directly) rather than handing through the raw keyring entry — the
79	// keyring stores the auth-host-issued core token, which the data API
80	// rejects in split-host setups.
81	func newSessionsClient(token string) *api.Client {
82		return api.NewClientWithBaseURL(token, api.BaseURL()).
83			WithAuthTokensPath(auth.CurrentProvider().AuthTokensPath)
84	}
85	
86	// resolveDataAPIToken returns a bearer scoped for the data API. In
87	// split-host setups this triggers an RFC 8693 exchange against the
88	// auth host's STS endpoint; in single-host setups the tokenmanager
89	// hits the same-host shortcut and returns the core token unchanged.
90	// Centralised so the audience-mismatch bug that motivated this fix
91	// can't be reintroduced piecemeal at individual call sites.
92	func resolveDataAPIToken(ctx context.Context) (string, error) {
93		token, err := auth.TokenForResource(ctx, api.OriginOnly(api.BaseURL()))
94		if err != nil {
95			return "", fmt.Errorf("resolve API token: %w", err)
96		}
97		return token, nil
98	}
99	
100	// isKeychainTokenRejected reports whether err indicates the stored
101	// keyring token can't authenticate against the data API. Three failure
102	// modes collapse into this single "the user must re-login" branch:
103	//
104	//   - data API returned 401 (single-host, or after a successful STS
105	//     exchange whose result the data API then rejected),
106	//   - tokenmanager's preflight rejected an expired core token JWT
107	//     (surfacing as auth.ErrNotLoggedIn even though the keyring entry
108	//     is still present),
109	//   - the STS endpoint rejected the core token during exchange in a
110	//     split-host setup. auth-go's sts package returns the response as
111	//     "token exchange: status 4xx: <code>[: <desc>]" with no typed
112	//     sentinel exposed, so detection has to be by prefix. The "status
113	//     4" anchor catches the entire 4xx range — every 4xx from STS is
114	//     a credential problem, none are retryable without user action.
115	//
116	// Other shapes (network errors, malformed STS response, manager
117	// construction failures) deliberately don't match — the user sees the
118	// real diagnostic instead of a misleading "re-login" hint.
119	func isKeychainTokenRejected(err error) bool {
120		if api.IsHTTPErrorStatus(err, http.StatusUnauthorized) {
121			return true
122		}
123		// The /me liveness probe goes through the core API client, whose 401
124		// surfaces as *coreapi.ErrorModelStatusCode rather than api.HTTPError.
125		var coreErr *coreapi.ErrorModelStatusCode
126		if errors.As(err, &coreErr) && coreErr.StatusCode == http.StatusUnauthorized {
127			return true
128		}
129		if errors.Is(err, auth.ErrNotLoggedIn) {
130			return true
131		}
132		return strings.Contains(err.Error(), "token exchange: status 4")
133	}
