197	// (or an expired login that can't be exchanged) means the stored token is no
198	// longer usable, which isKeychainTokenRejected maps to a re-login hint.
199	func defaultFetchProfile(ctx context.Context) (*authProfile, error) {
200		client, err := coreapi.New()
201		if err != nil {
202			return nil, fmt.Errorf("connect to Entire control plane: %w", err)
