253		fmt.Fprintf(outW, "Logged in to %s\n", baseURL)
254		writeProfileLines(outW, profile)
255		fmt.Fprintf(outW, "  %-9s %s\n", "Token:", "stored in OS keychain")
256		fmt.Fprintln(outW)
