277	// writeProfileLines renders the user identity from GET /me as aligned
278	// label/value lines, omitting any field the server didn't populate.
279	func writeProfileLines(w io.Writer, p *authProfile) {
280		var parts []string
281		if p.DisplayName != "" {
282			parts = append(parts, p.DisplayName)
283		}
284		if p.Handle != "" {
285			parts = append(parts, "@"+p.Handle)
286		}
287		if p.Email != "" {
288			parts = append(parts, "<"+p.Email+">")
289		}
290		if len(parts) > 0 {
291			fmt.Fprintf(w, "  %-9s %s\n", "User:", strings.Join(parts, " "))
292		}
293		if p.Provider != "" {
294			identity := p.Provider
295			if p.ProviderUserID != "" {
296				identity += "/" + p.ProviderUserID
297			}
298			fmt.Fprintf(w, "  %-9s %s\n", "Identity:", identity)
