302	// sortSessionsByRecency orders sessions most-recently-used first, then most
303	// recently created, then by id — a fully specified order independent of the
304	// server's response ordering.
305	func sortSessionsByRecency(sessions []api.Session) {
306		sort.Slice(sessions, func(i, j int) bool {
307			li := lastUsedSortKey(sessions[i])
308			lj := lastUsedSortKey(sessions[j])
309			if li != lj {
310				return li > lj
311			}
312			if sessions[i].CreatedAt != sessions[j].CreatedAt {
313				return sessions[i].CreatedAt > sessions[j].CreatedAt
314			}
315			return sessions[i].ID < sessions[j].ID
316		})
317	}
