352	
353	func (s authTableStyles) render(style lipgloss.Style, text string) string {
354		if !s.colorEnabled {
355			return text
356		}
357		return style.Render(text)
358	}
359	
360	// renderSessionsTable prints a styled, column-aligned table of login sessions.
361	// Column padding is computed via lipgloss.Width — it strips ANSI escapes, so a
362	// styled cell's visible width matches its plain text. tabwriter can't be used
363	// here once cells contain ANSI codes.
364	func renderSessionsTable(w io.Writer, sty authTableStyles, tokens []api.Session, now time.Time) {
365		headerCells := []string{"ID", "NAME", "SCOPE", "CREATED", "LAST USED", "EXPIRES"}
366		header := make([]string, len(headerCells))
367		for i, h := range headerCells {
368			header[i] = sty.render(sty.header, h)
369		}
370	
371		rows := make([][]string, 0, len(tokens))
372		for _, t := range tokens {
373			rows = append(rows, []string{
374				sty.render(sty.id, t.ID),
375				styleName(sty, t.Name),
376				sty.render(sty.value, fallback(t.Scope, placeholderDash)),
377				sty.render(sty.value, formatAuthDate(t.CreatedAt)),
378				styleLastUsed(sty, t.LastUsedAt, now),
379				styleExpires(sty, t.ExpiresAt, now),
380			})
381		}
382	
383		renderAlignedTable(w, header, rows)
384	}
385	
386	// renderAlignedTable writes header followed by rows in left-aligned columns,
387	// sizing each column to its widest (possibly pre-styled) cell. Column widths
388	// use lipgloss.Width so ANSI escapes don't inflate the padding. Shared by the
389	// auth-status and auth-contexts tables.
390	func renderAlignedTable(w io.Writer, header []string, rows [][]string) {
391		widths := make([]int, len(header))
392		for i, h := range header {
393			widths[i] = lipgloss.Width(h)
394		}
395		for _, row := range rows {
396			for i, c := range row {
397				if cw := lipgloss.Width(c); cw > widths[i] {
398					widths[i] = cw
399				}
400			}
401		}
402	
403		writeRow(w, header, widths)
404		for _, row := range rows {
405			writeRow(w, row, widths)
406		}
407	}
408	
409	func writeRow(w io.Writer, cells []string, widths []int) {
410		for i, c := range cells {
411			fmt.Fprint(w, c)
412			if i < len(cells)-1 {
413				fmt.Fprint(w, strings.Repeat(" ", widths[i]-lipgloss.Width(c)+2))
414			}
415		}
416		fmt.Fprintln(w)
417	}
418	
419	func styleName(sty authTableStyles, name string) string {
420		if name == "" {
421			return sty.render(sty.dim, placeholderDash)
422		}
423		return sty.render(sty.name, name)
424	}
425	
426	func styleLastUsed(sty authTableStyles, lastUsed *string, now time.Time) string {
427		if lastUsed == nil {
428			return sty.render(sty.dim, lastUsedNever)
429		}
430		return sty.render(sty.value, formatAuthLastUsed(lastUsed, now))
431	}
432	
433	func styleExpires(sty authTableStyles, expiresAt string, now time.Time) string {
434		formatted := formatAuthDate(expiresAt)
435		switch classifyExpiresAt(expiresAt, now) {
436		case expiresExpired:
437			return sty.render(sty.expired, formatted)
438		case expiresSoon:
439			return sty.render(sty.warning, formatted)
440		case expiresNormal:
441			return sty.render(sty.value, formatted)
442		}
443		return sty.render(sty.value, formatted)
444	}
445	
446	func lastUsedSortKey(t api.Session) string {
447		if t.LastUsedAt == nil {
448			return ""
449		}
450		return *t.LastUsedAt
451	}
452	
453	// formatAuthDate renders an RFC3339 timestamp as YYYY-MM-DD in local time.
454	func formatAuthDate(s string) string {
455		if s == "" {
456			return placeholderDash
457		}
458		if ts, err := time.Parse(time.RFC3339, s); err == nil {
459			return ts.Local().Format("2006-01-02")
460		}
461		return s
462	}
463	
464	// formatAuthLastUsed renders a relative "last used" timestamp, with "yesterday"
465	// and absolute-date branches that the shared formatRelativeDuration helper
466	// doesn't cover.
467	func formatAuthLastUsed(s *string, now time.Time) string {
468		if s == nil || *s == "" {
469			return lastUsedNever
470		}
471		ts, err := time.Parse(time.RFC3339, *s)
472		if err != nil {
473			return *s
474		}
475		delta := now.Sub(ts)
476		switch {
477		case delta < 0, delta >= 30*24*time.Hour:
478			return ts.Local().Format("2006-01-02")
479		case delta >= 24*time.Hour && delta < 48*time.Hour:
480			return "yesterday"
481		default:
482			return formatRelativeDuration(delta)
483		}
484	}
485	
486	type expiresState int
487	
488	const (
489		expiresNormal expiresState = iota
490		expiresSoon
491		expiresExpired
492	)
493	
494	// classifyExpiresAt classifies an RFC3339 expires-at relative to now. Used to
495	// color the EXPIRES column so tokens worth rotating stand out.
496	func classifyExpiresAt(s string, now time.Time) expiresState {
497		if s == "" {
498			return expiresNormal
499		}
500		ts, err := time.Parse(time.RFC3339, s)
501		if err != nil {
502			return expiresNormal
503		}
504		delta := ts.Sub(now)
505		switch {
506		case delta <= 0:
507			return expiresExpired
508		case delta < 7*24*time.Hour:
509			return expiresSoon
510		default:
511			return expiresNormal
512		}
513	}
514	
515	func fallback(s, alt string) string {
516		if strings.TrimSpace(s) == "" {
517			return alt
518		}
519		return s
520	}
