289		store := newMockTokenStore()
290		store.tokens[testBaseURL] = testAuthTok
291	
292		list := func(context.Context) ([]api.Session, error) { return nil, nil }
293	
294		var out, errOut bytes.Buffer
295		if err := runAuthStatus(context.Background(), &out, &errOut, store, okProfile, list, testBaseURL); err != nil {
